mapper.select:


    DELETED = 0

        AND ENTERPRISE_ID = #{queryVO.enterpriseId}


        AND ENTERPRISE_NAME LIKE CONCAT('%', #{queryVO.enterpriseName}, '%')


        AND STATEMENT_TYPE = #{queryVO.statementType}


        AND PERIOD_TYPE = #{queryVO.periodType}


        AND REPORT_YEAR = #{queryVO.reportYear}


        AND REPORT_PERIOD = #{queryVO.reportPeriod}


        AND AUDIT_STATUS = #{queryVO.auditStatus}


        AND STATEMENT_STATUS = #{queryVO.statementStatus}


        AND DATA_QUALITY_LEVEL = #{queryVO.dataQualityLevel}


        AND RISK_LEVEL = #{queryVO.riskLevel}


        AND HAS_ANOMALIES = #{queryVO.hasAnomalies}


        AND NEED_REGULATORY_ATTENTION = #{queryVO.needRegulatoryAttention}


        AND COMPLIANCE_CHECK_RESULT = #{queryVO.complianceCheckResult}


        AND PREPARED_DATE >= #{queryVO.startPreparedDate}


        AND PREPARED_DATE <= #{queryVO.endPreparedDate}


ORDER BY REPORT_YEAR DESC, REPORT_PERIOD DESC, CREATE_TIME DESC
